#include <stdio.h>

void hodnotou(int x)
{
    x = 99;
}

void odkazem(int *x)
{
    *x = 42;
}

int main(void)
{
    int a = 1;

    hodnotou(a);
    printf("%d\n", a);

    odkazem(&a);
    printf("%d\n", a);

    return 0;
}
